/**
 * @marula-core/ui-native — the handoff kit's design values for React Native.
 *
 * `generated.ts` is written by `packages/ui/tokens/generate.mjs` from
 * `tokens/tokens.json`, the same file the web tokens come from, so the two
 * platforms cannot drift. Do not edit it by hand; run
 * `pnpm --filter @marula-core/ui tokens`.
 *
 * The app's own token module (`native/src/ui/tokens.ts`) builds its React
 * Native theme from these values; `native/tests/token-parity.test.ts` pins it.
 */
export * from "./generated";

// `icons/marula-icons.native.tsx` is deliberately NOT re-exported here. It is
// generated by `design/marula-handoff-kit/kit/scripts/icons-to-native.py` and
// carries that script's own warning that it is untested in a React Native
// app — and it turns out not even to transform in a Node test runner, so
// re-exporting it would make `@marula-core/ui-native` unusable from the native
// unit suite. Wiring the Marula glyphs into the app is a separate lane that
// fixes the generator first. Nothing else in the app consumes it today.
